const body = $input.first().json.body;
const hojaId = parseInt(body.hoja_id, 10);
return [{ json: { query: `SELECT * FROM crm_bybusiness.hojas_venta WHERE id = ${hojaId}`, hoja_id: hojaId, admin_id: parseInt(body.admin_id, 10) } }];

const hoja = $('Cargar Hoja Venta').first().json;
const adminId = $('Build SELECT Hoja').first().json.admin_id;
return [{ json: { query: `SELECT id, email, nombre FROM auth.usuarios WHERE id = ${adminId}`, _hoja: hoja, _admin_id: adminId } }];

const hojaId = $('Build SELECT Hoja').first().json.hoja_id;
const adminId = $('Build SELECT Hoja').first().json.admin_id;
return [{ json: { query: `UPDATE crm_bybusiness.hojas_venta SET estado = 'enviada', admin_destino_id = ${adminId}, updated_at = NOW() WHERE id = ${hojaId}`, _hoja: $('Build SELECT Admin').first().json._hoja, _admin: $input.first().json } }];

const ctx = $('Build UPDATE').first().json;
const hoja = ctx._hoja;
const adminId = $('Build SELECT Hoja').first().json.admin_id;
const hojaId = $('Build SELECT Hoja').first().json.hoja_id;
const esc = (v) => v == null ? '' : String(v);
const mensaje = `Nueva hoja de venta pendiente: ${esc(hoja.nombre_comercial)} - ${esc(hoja.precio_con_iva)} EUR`;
return [{ json: { query: `INSERT INTO crm_bybusiness.notificaciones_admin (tipo, referencia_id, admin_id, mensaje, leida) VALUES ('hoja_venta_pendiente', ${hojaId}, ${adminId}, '${mensaje.replace(/'/g, "''")}', false)`, _hoja: hoja, _admin: ctx._admin } }];

